export function fashionPreview(src: string, fit: 'contain' | 'cover' = 'contain', progressive = false): CSSProperties | undefined {
  const preview = previews[src];
  return preview ? { backgroundImage: progressive ? `url("${src.replace('/muraka-fashion/','/muraka-fashion/preview80/')}"), url("${preview}")` : `url("${preview}")`, backgroundPosition: progressive ? 'center, center' : 'center', backgroundSize: progressive ? `${fit}, ${fit}` : fit, backgroundRepeat: progressive ? 'no-repeat, no-repeat' : 'no-repeat' } : undefined;
}
export function clearFashionPreview(event: SyntheticEvent<HTMLImageElement>): void { const image=event.currentTarget, source=image.currentSrc, requested=image.getAttribute('src'); const clear=()=>{if(image.isConnected && image.currentSrc===source && image.getAttribute('src')===requested && image.complete && image.naturalWidth) image.style.backgroundImage='none';}; if(typeof image.decode==='function') void image.decode().then(clear).catch(clear); else clear(); }
export function fallbackFashionPreview(event: SyntheticEvent<HTMLImageElement>): void {
  const image = event.currentTarget;
  const preview = previews[image.getAttribute('src') || ''];
  if (!preview) { image.style.backgroundImage = 'none'; return; }
  image.removeAttribute('srcset');
  image.src = preview;
}
